--
-- Triggers `documentrequest`
--
DELIMITER $$
CREATE TRIGGER `trg_request_before_update` BEFORE UPDATE ON `documentrequest` FOR EACH ROW BEGIN
  IF NEW.status = 'Released' AND OLD.status <> 'Released' AND NEW.release_date IS NULL THEN
    SET NEW.release_date = CURRENT_DATE();
  END IF;
END
$$
DELIMITER ;

