--
-- Stand-in structure for view `vw_request_balances`
-- (See below for the actual view)
--
CREATE TABLE `vw_request_balances` (
`request_id` int(11)
,`resident_id` int(11)
,`resident_name` varchar(102)
,`type_name` varchar(50)
,`purpose` varchar(150)
,`status` varchar(20)
,`request_date` date
,`release_date` date
,`fee_charged` decimal(10,2)
,`total_paid` decimal(32,2)
,`balance` decimal(33,2)
);

-- --------------------------------------------------------

--
-- Structure for view `vw_request_balances`
--
DROP TABLE IF EXISTS `vw_request_balances`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`127.0.0.1` SQL SECURITY DEFINER VIEW `vw_request_balances`  AS SELECT `dr`.`request_id` AS `request_id`, `dr`.`resident_id` AS `resident_id`, concat(`r`.`last_name`,', ',`r`.`first_name`) AS `resident_name`, `dt`.`type_name` AS `type_name`, `dr`.`purpose` AS `purpose`, `dr`.`status` AS `status`, `dr`.`request_date` AS `request_date`, `dr`.`release_date` AS `release_date`, `dr`.`fee_charged` AS `fee_charged`, coalesce(sum(`p`.`amount_paid`),0) AS `total_paid`, `dr`.`fee_charged`- coalesce(sum(`p`.`amount_paid`),0) AS `balance` FROM (((`documentrequest` `dr` join `resident` `r` on(`r`.`resident_id` = `dr`.`resident_id`)) join `documenttype` `dt` on(`dt`.`doctype_id` = `dr`.`doctype_id`)) left join `payment` `p` on(`p`.`request_id` = `dr`.`request_id`)) GROUP BY `dr`.`request_id`, `dr`.`resident_id`, `r`.`last_name`, `r`.`first_name`, `dt`.`type_name`, `dr`.`purpose`, `dr`.`status`, `dr`.`request_date`, `dr`.`release_date`, `dr`.`fee_charged` ;

